bool loadModel(const std::string& fileName, std::pair<Backend, Target> conf)
{
    if( !setDevice(conf.second) )
    {
        printf("cannot set device");
        return false;
    }

    if( !fileExists(fileName) )
    {
        printf("model does not exist");
        return false;
    }
    
    net = cv::dnn::readNetFromONNX(fileName);

    if( net.empty() )
    {
        printf("empty network");
        return false;
    }

    net.setPreferableBackend(conf.first);
    net.setPreferableTarget(conf.second);
}
```

