Selecting the Nvidia card
```c++
bool setDevice(cv::dnn::Target target)
{
#ifdef HAVE_CUDA
    if( target == cv::dnn::DNN_TARGET_CUDA || target == cv::dnn::DNN_TARGET_CUDA_FP16 )
    {
        if( !hasCudaDevice(target) ) return false;
        int d = getFirstCudaDevice();
        if( d<0 ) return false;
        cv::cuda::setDevice(d);
    }
#endif
}
```

